import{_ as r,o as e,c as t,a5 as o}from"./chunks/framework.BTidRIrv.js";const _=JSON.parse('{"title":"1. 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"tr/index.md","filePath":"tr/index.md"}'),i={name:"tr/index.md"};function l(n,a,h,d,s,c){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="_1-介绍" tabindex="-1">1. 介绍 <a class="header-anchor" href="#_1-介绍" aria-label="Permalink to &quot;1. 介绍&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>注意，本wiki是为新版trapdoor(1.19+)准备的，不适用于旧版</strong></p></div><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>Trapdoor 是一个服务于Minecraft 基岩版专用服务器(BDS)的插件mod，可以让你更清晰地了解到游戏是如何运行的。简单来说Trapdoor是专为MCBE生电服务的一个BDS mod。Trapdoor提供了诸如世界运行速度调整，村庄机制可视化，硬编码结构刷怪区域(HSA)可视化，假人，MSPT和TPS查看，漏斗计数器，实体数量分析，刷怪概率分析，等等功能，更多功能还在持续增加中。</p><h2 id="插件特色" tabindex="-1">插件特色 <a class="header-anchor" href="#插件特色" aria-label="Permalink to &quot;插件特色&quot;">​</a></h2><ul><li>本插件完全<strong>尊重原版(Vanilla)游戏机制，绝不会在玩家不知道的时候修改游戏机制，所有修改游戏机制的行为都会完全告知玩家</strong>，具体细节请参考使用页面。</li><li>支持多人游戏</li><li>配置文件高度可自定义</li><li>持续更新(咕咕咕)</li></ul><h2 id="你可能会关心的的事情" tabindex="-1">你可能会关心的的事情 <a class="header-anchor" href="#你可能会关心的的事情" aria-label="Permalink to &quot;你可能会关心的的事情&quot;">​</a></h2><h3 id="关于开发者" tabindex="-1">关于开发者 <a class="header-anchor" href="#关于开发者" aria-label="Permalink to &quot;关于开发者&quot;">​</a></h3><p>目前主要的开发者有两位</p><ol><li><a href="https://github.com/hhhxiao" target="_blank" rel="noreferrer">hhhxiao</a> Trapdoor的主要开发者</li><li><a href="https://github.com/OEOTYAN" target="_blank" rel="noreferrer">OEOTYAN</a> 主要负责部分算法的实现以及<a href="https://github.com/OEOTYAN/Trapdoor-CUI" target="_blank" rel="noreferrer">插件所需要的配套纹理包</a>的编写工作</li></ol>',10)])])}const u=r(i,[["render",l]]);export{_ as __pageData,u as default};
